{
  "name": "🛠️dev👤compose⌨️vscode",
  "type": "extensionHost",
  "request": "launch",
  "args": [
    "--extensionDevelopmentPath=${workspaceFolder}/compose/vscode"
  ],
  "outFiles": [
    "${workspaceFolder}/compose/vscode/out/**/*.js"
  ],
  "preLaunchTask": "🛠️dev👤compose⌨️vscode"
},
{
  "name": "🛠️dev👤compose⌨️vscode (integrated)",
  "type": "node-terminal",
  "request": "launch",
  "command": "npx nx dev compose/vscode",
  "isBackground": true,
  "problemMatcher": {
    "owner": "typescript",
    "fileLocation": "relative",
    "pattern": {
      "regexp": "^([^\\s].*?):(\\d+):(\\d+):\\s+(error|warning):\\s+(.*)$",
      "file": 1,
      "line": 2,
      "column": 3,
      "severity": 4,
      "message": 5
    },
    "background": {
      "activeOnStart": true,
      "beginsPattern": ".*vite.*building",
      "endsPattern": ".*built in.*"
    }
  },
  "presentation": {
    "reveal": "always",
    "panel": "dedicated"
  },
  "cwd": "${workspaceFolder}"
},

{
  "name": "🛠️dev👤compose📚engine🤖mcp",
  "type": "node",
  "request": "launch",
  "runtimeExecutable": "uv",
  "runtimeArgs": [
    "--directory",
    "compose/engine",
    "run",
    "main.py",
    "--mcp-stdio"
  ],
  "cwd": "${workspaceFolder}",
  "console": "integratedTerminal",
  "serverReadyAction": {
    "action": "openExternally",
    "pattern": "(http://[^\\s]+:6274)",
    "uriFormat": "%s"
  }
},
{
  "name": "🛠️dev👤compose📚engine🤖mcp (with inspector)",
  "type": "node-terminal",
  "request": "launch",
  "command": "npm run mcp:inspector",
  "isBackground": true,
  "options": {
    "cwd": "${workspaceFolder}"
  },
  "problemMatcher": {
    "owner": "custom",
    "pattern": [
      {
        "regexp": ".",
        "file": 1,
        "location": 2,
        "message": 3
      }
    ],
    "background": {
      "activeOnStart": true,
      "beginsPattern": "Starting MCP",
      "endsPattern": ":6274"
    }
  },
  "cwd": "${workspaceFolder}",
  "serverReadyAction": {
    "action": "openExternally",
    "pattern": "(http://[^\\s]+:6274)",
    "uriFormat": "%s"
  }
},

